            json.dump({"t": self._now(), "v": value}, f)

    def get(self, key, default=None):
        p = self._path(key)
        if not os.path.exists(p):
            return default
        try:
            with open(p) as f:
                rec = json.load(f)
        except Exception:
            # corrupted file: remove and treat as missing
            try:
                os.remove(p)
            except OSError:
                pass
            return default
